import {learnerLine} from './learner-voice.js';
import {cartoonCast as cast, plantDrawing, leafDrawing} from './factory-art.js?v=3';
import {icon,title,next,complete,state,escapeHTML} from './app.js?v=8';
const demo = [
  {focus:'water', who:'Water', line:'Up we go! Roots absorb water. It travels inside the stem and into the veins of the leaves. Follow the blue route!', seconds:9},
  {focus:'air', who:'Sprout', line:'Carbon dioxide is a gas in the air. It enters through tiny openings in a leaf.', seconds:9},
  {focus:'light', who:'Sprout', line:'Watch the cloud move away. Sunlight can now reach the leaf.', seconds:6},
  {focus:'chlorophyll', who:'Sprout', line:'The green chloroplasts inside leaf cells contain chlorophyll. This green pigment absorbs sunlight. This gives the process energy!', seconds:10},
  {focus:'make', who:'Sprout', line:'With that energy, the leaf uses water and carbon dioxide to make glucose, a sugar, and oxygen.', seconds:10},
  {focus:'gifts', who:'Sprout', line:'Glucose is my food. Some is stored as starch. Oxygen goes into the air. Living things use it to breathe!', seconds:11}
];
const focusLabels={water:'BLUE WATER ROUTE',air:'TINY LEAF OPENING',light:'THE SUN',chlorophyll:'GREEN CHLOROPLASTS',make:'INSIDE THE LEAF',gifts:'GLUCOSE + OXYGEN'};
const demoTitles=['Water travels up the plant','Carbon dioxide enters the leaf','Sunlight reaches the leaf','Chlorophyll absorbs light','The leaf makes food','Glucose and oxygen'];
const demoHints=['Start at the circled root. Follow the blue drop up to the leaf.','This is a close-up of the selected leaf. Watch the circled opening underneath it.','Look at the circled Sun. Watch the cloud move away.','Now look inside that same leaf. Chlorophyll in these green ovals absorbs light energy.','Look inside the leaf: water and carbon dioxide are used to make food.','Look for G inside the leaf and O₂ leaving through the opening.'];

const $=s=>document.querySelector(s);
let step=0,loop,elapsed=0,lastTick=0,started=false,paused=false,voices=false,phase='video';
function cancel(){clearInterval(loop);loop=null;if('speechSynthesis'in window)speechSynthesis.cancel()}
export function cleanupFactory(){cancel();document.removeEventListener('visibilitychange',onVisibility);$('#settings')?.removeEventListener('click',onSettings)}
function speak(text){if(!voices||!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.94;speechSynthesis.speak(u)}
function say(who,text){$('#factory-speaker').textContent=who;$('#factory-line').textContent=text;$('#guide-face').innerHTML=cast(who==='Water'?'drop':'sprout');speak(text)}
function stage(){return `<div class="leaf-workshop svg-workshop demonstrating is-waiting" id="leaf-workshop" data-focus="${demo[step].focus}"><div class="science-scenes"><section class="plant-panel" aria-label="The whole plant"><div class="scene-heading"><span class="scene-number">1</span><div><b>Follow the water</b><small>Roots → stem → leaf</small></div></div>${plantDrawing()}</section><section class="leaf-panel" aria-label="A closer look at the same leaf"><div class="scene-heading"><span class="scene-number">2</span><div><b>A closer look</b><small>A slice through that same leaf</small></div></div>${leafDrawing()}</section></div><div id="factory-status" class="science-status" role="status">Press Start when you are ready.</div></div>`}
export function factory(){return title('story','Sprout’s food-making secret',escapeHTML(learnerLine('{name}, watch the story, then explore photosynthesis one step at a time.','Watch the story, then explore photosynthesis one step at a time.')))+`<section class="leaf-experience guided-factory" aria-label="Video and guided photosynthesis lesson"><div class="experience-bar"><div class="episode-tags"><span id="chapter-film" class="active">1 · Video</span><span id="chapter-demo">2 · Inside the leaf</span></div><button id="factory-voice" class="text-btn" aria-pressed="false" hidden>${icon('volume')} <span>Voices off</span></button></div><div class="factory-narrator" hidden><div id="guide-face">${cast('sprout')}</div><div class="narrator-caption" aria-live="polite" aria-atomic="true"><div class="narrator-meta"><b id="factory-speaker">Sprout</b><span id="factory-look" class="narrator-look" hidden>LOOK AT: <span id="factory-look-text"></span>${icon('arrow')}</span></div><p id="factory-line"></p></div><button id="replay-line" class="icon-btn" aria-label="Read this caption aloud">${icon('volume')}</button></div><div id="factory-visual"><div class="lesson-video"><iframe src="https://www.youtube-nocookie.com/embed/DJnnWQehI50?autoplay=0&rel=0&playsinline=1" title="Sprout and Beep — photosynthesis cartoon" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><div class="lesson-video-note"><p>Play the video when you’re ready. Use Next to look inside the leaf.</p><a href="https://youtu.be/DJnnWQehI50" target="_blank" rel="noopener noreferrer">Open video on YouTube</a></div><button id="lesson-next" class="btn yellow" data-label="Next: inside the leaf">Next: inside the leaf ${icon('arrow')}</button></div><div class="episode-progress" aria-hidden="true"><span id="episode-progress"></span></div></section><details class="transcript"><summary>Photosynthesis notes</summary>${demo.map(x=>`<p>${x.line}</p>`).join('')}<p><b>Water + carbon dioxide → glucose + oxygen</b>, using light energy absorbed by chlorophyll. Some glucose is stored as starch. Sunlight supplies energy; it is not a raw material. Plants also respire during day and night.</p><p class="caption">A simplified model. Drawings are enlarged; moving symbols show routes and processes. Science Year 4 · Unit 4 · printed pages 76–81.</p></details>`+next('story','Try the leaf lab',true)}
export function bindFactory(){cleanupFactory();phase='video';step=0;voices=!!state.settings.sound;updateVoice();$('#lesson-next').onclick=()=>{step=0;showStep()};$('#factory-voice').onclick=()=>{voices=!voices;updateVoice();if(voices&&started)speak($('#factory-line').textContent);else if('speechSynthesis'in window)speechSynthesis.cancel()};$('#replay-line').onclick=()=>{voices=true;updateVoice();speak($('#factory-line').textContent)};document.addEventListener('visibilitychange',onVisibility);$('#settings')?.addEventListener('click',onSettings)}
function updateVoice(){$('#factory-voice').setAttribute('aria-pressed',String(voices));$('#factory-voice span').textContent=voices?'Voices on':'Voices off'}
function onVisibility(){if(document.hidden&&phase==='lesson'&&started&&!paused)pause()}
function onSettings(){if(phase==='lesson'&&started&&!paused)pause()}
function pause(){paused=!paused;$('.leaf-experience').classList.toggle('is-paused',paused);$('#lesson-pause').textContent=paused?'Resume':'Pause';lastTick=performance.now();if('speechSynthesis'in window){if(paused)speechSynthesis.pause();else speechSynthesis.resume()}}
function apply(index){const s=$('#leaf-workshop');if(index===0)s.classList.add('water-arrived');if(index===1)s.classList.add('gas-arrived');if(index===2){s.style.setProperty('--sunlight',1);s.classList.add('light-arrived')}if(index===4)s.classList.add('is-making');if(index===5){s.classList.remove('is-making');s.classList.add('has-products')}}
function showStep(autoStart=false){cancel();phase='lesson';started=false;paused=false;elapsed=0;$('.leaf-experience').classList.remove('is-paused');$('.factory-narrator').hidden=false;$('#factory-voice').hidden=false;$('#chapter-film').classList.remove('active');$('#chapter-demo').classList.add('active');$('#factory-look').hidden=true;$('#episode-progress').style.width=(step/demo.length*100)+'%';$('#factory-visual').innerHTML=`<div class="demo-controls" id="demo-controls"><div><h2 id="demo-title" tabindex="-1">Step ${step+1} of ${demo.length} · ${demoTitles[step]}</h2><p id="demo-instruction">Press Start once to begin. Next starts the following step.</p></div><div class="demo-buttons"><button id="lesson-start" class="btn yellow">${icon('play')} Start this step</button><button id="lesson-pause" class="text-btn" hidden>Pause</button><button id="lesson-next" class="btn yellow" data-local-forward="true" data-label="${step===demo.length-1?'Next: finish lesson':'Next step'}" disabled>Next step ${icon('arrow')}</button></div></div>${stage()}`;for(let i=0;i<step;i++)apply(i);$('#factory-line').textContent=learnerLine('Ready, {name}? Start this step to see what happens.','Start this step to see what happens.');$('#factory-speaker').textContent='Sprout';$('#lesson-start').onclick=startStep;$('#lesson-pause').onclick=pause;$('#lesson-next').onclick=()=>{cancel();if(step===demo.length-1)finish();else{step++;showStep(true)}};$('#demo-title').focus({preventScroll:true});$('.leaf-experience').scrollIntoView({block:'start',behavior:'instant'});if(autoStart)startStep()}
function startStep(){cancel();started=true;paused=false;elapsed=0;$('.leaf-experience').classList.remove('is-paused');const s=$('#leaf-workshop');s.classList.remove('is-waiting','lesson-settled');$('#lesson-next').disabled=false;$('#lesson-start').innerHTML=icon('play')+' Replay step';$('#lesson-pause').hidden=false;$('#lesson-pause').textContent='Pause';$('#demo-instruction').textContent=demoHints[step];$('#factory-look-text').textContent=focusLabels[demo[step].focus];$('#factory-look').hidden=false;say(demo[step].who,demo[step].line);$('#factory-status').textContent=demo[step].line;if(step===2){s.style.setProperty('--sunlight',0);s.classList.remove('light-arrived')}lastTick=performance.now();animate();loop=setInterval(()=>{const now=performance.now();if(!paused){elapsed+=(now-lastTick)/1000;animate();if(elapsed>=6){clearInterval(loop);loop=null;s.classList.add('lesson-settled');$('#lesson-pause').hidden=true;$('#demo-instruction').textContent='Take your time. Replay this step or use Next when you’re ready.';$('#episode-progress').style.width=((step+1)/demo.length*100)+'%'}}lastTick=now},40)}
function animate(){const progress=Math.min(1,elapsed/5);const reduced=state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;apply(step);if(step===0||step===1){const path=$(step===0?'#water-route':'#demo-gas-route'),dot=$(step===0?'#water-traveller':'#carbon-traveller'),p=path.getPointAtLength(path.getTotalLength()*(reduced?1:progress));dot.setAttribute('r',step===0?'9':'10');dot.setAttribute('transform',`translate(${p.x} ${p.y})`);dot.setAttribute('visibility',progress<1&&!reduced?'visible':'hidden')}if(step===2){$('#leaf-workshop').style.setProperty('--sunlight',reduced?1:progress);$('#leaf-workshop').classList.toggle('light-arrived',reduced||progress===1)}}
function finish(){cancel();phase='finished';$('.leaf-experience').classList.remove('is-paused');$('#factory-visual').innerHTML=`<div class="demo-intro"><h2 tabindex="-1">The leaf has made food</h2><p>Some glucose is stored as starch. Oxygen is released into the air.</p><p>Use Next adventure to try the leaf lab.</p></div>${stage()}`;for(let i=0;i<demo.length;i++)apply(i);$('#leaf-workshop').classList.add('lesson-settled');$('#factory-status').textContent='Glucose made; some stored as starch. Oxygen released into the air.';$('#factory-look').hidden=true;say('Sprout',learnerLine('Thanks, {name}! Now test what happens when a leaf is missing one of its needs.','Now test what happens when a leaf is missing one of its needs.'));$('#episode-progress').style.width='100%';complete('story');$('#factory-visual h2').focus({preventScroll:true})}
